package com.yongdrel.payment_proof_service.config;
import jakarta.servlet.DispatcherType; import org.springframework.context.annotation.*; import org.springframework.http.HttpMethod; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.web.SecurityFilterChain;
@Configuration public class SecurityConfig{@Bean SecurityFilterChain chain(HttpSecurity h)throws Exception{return h.csrf(c->c.disable()).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.dispatcherTypeMatchers(DispatcherType.ERROR).permitAll().requestMatchers("/actuator/health","/actuator/info").permitAll().requestMatchers(HttpMethod.POST,"/api/payment-proofs").authenticated().requestMatchers(HttpMethod.GET,"/api/payment-proofs/**").authenticated().requestMatchers(HttpMethod.PATCH,"/api/payment-proofs/**").authenticated().requestMatchers("/internal/payment-proofs/**").permitAll().anyRequest().denyAll()).oauth2ResourceServer(o->o.jwt(j->{})).build();}}
